from collections import deque, Counter

def comps(cells):
    cells=set(cells); out=[]
    while cells:
        p=next(iter(cells)); cells.remove(p); q=[p]; comp={p}
        while q:
            r,c=q.pop()
            for x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if x in cells: cells.remove(x);comp.add(x);q.append(x)
        out.append(comp)
    return out
